const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'cover', index: 1, title: 'VAPO Cover' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Accent bar top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06, fill: { color: theme.accent }
  });

  // Large title
  slide.addText("VAPO", {
    x: 0.6, y: 0.8, w: 8.8, h: 1.2,
    fontSize: 72, fontFace: "Georgia", bold: true,
    color: "FFFFFF", align: "left", margin: 0
  });

  // Subtitle
  slide.addText("Value-Model-Based Reinforcement Learning\nfor Advanced Reasoning", {
    x: 0.6, y: 2.0, w: 8.8, h: 0.9,
    fontSize: 22, fontFace: "Calibri",
    color: theme.light, align: "left", margin: 0
  });

  // Divider line
  slide.addShape(pres.shapes.LINE, {
    x: 0.6, y: 3.1, w: 3.5, h: 0,
    line: { color: theme.accent, width: 2.5 }
  });

  // Key result callout
  slide.addText("60.4 on AIME 2024", {
    x: 0.6, y: 3.35, w: 5, h: 0.6,
    fontSize: 28, fontFace: "Georgia", bold: true,
    color: theme.accent, align: "left", margin: 0
  });

  slide.addText("Surpassing DAPO by 10+ points  |  No SFT data  |  Qwen2.5-32B base", {
    x: 0.6, y: 3.95, w: 7, h: 0.4,
    fontSize: 13, fontFace: "Calibri",
    color: "C8D6D0", align: "left", margin: 0
  });

  // Authors
  slide.addText("ByteDance Seed  •  arxiv.org/abs/2504.05118", {
    x: 0.6, y: 4.85, w: 5, h: 0.35,
    fontSize: 12, fontFace: "Calibri",
    color: "8AABA0", align: "left", margin: 0
  });

  // Big accent number on right
  slide.addText("60.4", {
    x: 5.5, y: 1.5, w: 4.2, h: 2.8,
    fontSize: 96, fontFace: "Georgia", bold: true,
    color: theme.accent, align: "right", margin: 0,
    transparency: 15
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e76f51", light: "f4a261", bg: "F5F0E8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

