const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 4, title: 'VAPO Framework Overview' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("VAPO Framework: Integrated Solutions", {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 24, fontFace: "Georgia", bold: true,
    color: theme.primary, align: "left", margin: 0
  });

  // Challenge headers across top
  const challenges = ["Value Model Bias", "Heterogeneous Lengths", "Reward Sparsity"];
  const colW = 2.85;
  const startX = 0.5;
  const gap = 0.2;
  const headerY = 0.95;

  challenges.forEach((ch, i) => {
    const cx = startX + i * (colW + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: headerY, w: colW, h: 0.4,
      fill: { color: theme.primary }
    });
    slide.addText(ch, {
      x: cx, y: headerY, w: colW, h: 0.4,
      fontSize: 12, fontFace: "Calibri", bold: true,
      color: "FFFFFF", align: "center", valign: "middle", margin: 0
    });
  });

  // Components mapped to challenges
  const components = [
    // Column 1: Value Model Bias
    [
      { name: "Value-Pretraining", desc: "Pre-trains value model before RL to reduce initial bias", novel: false },
      { name: "Decoupled-GAE", desc: "Separates GAE computation for robust value estimation (from VC-PPO)", novel: false }
    ],
    // Column 2: Heterogeneous Lengths
    [
      { name: "Length-Adaptive GAE", desc: "Dynamically adjusts λ based on response length (novel)", novel: true },
      { name: "Token-level Loss", desc: "Normalizes loss at token level, not sequence level (from DAPO)", novel: false }
    ],
    // Column 3: Reward Sparsity
    [
      { name: "Clip-Higher", desc: "Asymmetric clipping encourages exploration (from DAPO)", novel: false },
      { name: "Positive Example LM Loss", desc: "Self-imitation learning on correct trajectories", novel: false },
      { name: "Group-Sampling", desc: "Multiple responses per prompt for better baseline (from GRPO)", novel: false }
    ]
  ];

  const compStartY = 1.55;

  components.forEach((col, ci) => {
    const cx = startX + ci * (colW + gap);
    col.forEach((comp, ri) => {
      const cy = compStartY + ri * 1.15;
      const borderColor = comp.novel ? theme.accent : "D0D0D0";
      const bgColor = comp.novel ? "FFF5F0" : "FFFFFF";

      // Arrow from header
      if (ri === 0) {
        slide.addShape(pres.shapes.LINE, {
          x: cx + colW / 2, y: headerY + 0.4, w: 0, h: 0.15,
          line: { color: theme.secondary, width: 1.5 }
        });
      }

      slide.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: cy, w: colW, h: 1.0,
        fill: { color: bgColor },
        line: { color: borderColor, width: comp.novel ? 2 : 1 }
      });

      const labelParts = [{ text: comp.name, options: { bold: true, fontSize: 12, breakLine: true } }];
      if (comp.novel) {
        labelParts.push({ text: "  NOVEL", options: { bold: true, fontSize: 9, color: theme.accent, breakLine: true } });
      } else {
        labelParts.push({ text: "", options: { breakLine: true } });
      }
      labelParts.push({ text: comp.desc, options: { fontSize: 10, color: "666666" } });

      slide.addText(labelParts, {
        x: cx + 0.1, y: cy + 0.08, w: colW - 0.2, h: 0.85,
        fontFace: "Calibri", color: theme.primary,
        align: "left", valign: "top", margin: 0
      });
    });
  });

  // Bottom note
  slide.addText("Each technique targets a specific challenge — VAPO integrates all seven for stable, high-performance reasoning RL.", {
    x: 0.5, y: 4.9, w: 8.5, h: 0.3,
    fontSize: 11, fontFace: "Calibri", italic: true,
    color: theme.secondary, align: "left", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("4", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e76f51", light: "f4a261", bg: "F5F0E8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

