const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 5, title: 'Length-Adaptive GAE Deep Dive' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("Length-Adaptive GAE: Dynamic λ for Variable Response Lengths", {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 22, fontFace: "Georgia", bold: true,
    color: theme.primary, align: "left", margin: 0, fit: "shrink"
  });

  // Key insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.95, w: 9, h: 0.55,
    fill: { color: theme.primary }
  });
  slide.addText("Core Insight: A single fixed λ cannot serve both short and long responses — the optimal bias-variance tradeoff depends on sequence length.", {
    x: 0.7, y: 0.95, w: 8.6, h: 0.55,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", align: "left", valign: "middle", margin: 0
  });

  // Two-column: short vs long
  const leftX = 0.5;
  const rightX = 5.2;
  const boxW = 4.3;
  const boxY = 1.75;
  const boxH = 2.2;

  // Short responses
  slide.addShape(pres.shapes.RECTANGLE, {
    x: leftX, y: boxY, w: boxW, h: boxH,
    fill: { color: "FFFFFF" }, line: { color: theme.secondary, width: 1.5 }
  });
  slide.addText("Short Responses", {
    x: leftX, y: boxY + 0.1, w: boxW, h: 0.35,
    fontSize: 16, fontFace: "Georgia", bold: true,
    color: theme.secondary, align: "center", margin: 0
  });
  slide.addText("Lower λ", {
    x: leftX + 0.8, y: boxY + 0.55, w: 2.6, h: 0.45,
    fontSize: 28, fontFace: "Georgia", bold: true,
    color: theme.secondary, align: "center", margin: 0
  });
  slide.addText([
    { text: "Fewer tokens → less bootstrapping error", options: { bullet: true, breakLine: true } },
    { text: "Prioritizes lower variance", options: { bullet: true, breakLine: true } },
    { text: "More stable gradient estimates", options: { bullet: true } }
  ], {
    x: leftX + 0.2, y: boxY + 1.1, w: boxW - 0.4, h: 1.0,
    fontSize: 12, fontFace: "Calibri",
    color: "555555", align: "left", valign: "top", margin: 0, paraSpaceAfter: 4
  });

  // Long responses
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: boxY, w: boxW, h: boxH,
    fill: { color: "FFFFFF" }, line: { color: theme.accent, width: 1.5 }
  });
  slide.addText("Long Responses", {
    x: rightX, y: boxY + 0.1, w: boxW, h: 0.35,
    fontSize: 16, fontFace: "Georgia", bold: true,
    color: theme.accent, align: "center", margin: 0
  });
  slide.addText("Higher λ", {
    x: rightX + 0.8, y: boxY + 0.55, w: 2.6, h: 0.45,
    fontSize: 28, fontFace: "Georgia", bold: true,
    color: theme.accent, align: "center", margin: 0
  });
  slide.addText([
    { text: "More tokens → higher bootstrapping bias risk", options: { bullet: true, breakLine: true } },
    { text: "Prioritizes lower bias", options: { bullet: true, breakLine: true } },
    { text: "Better long-horizon credit assignment", options: { bullet: true } }
  ], {
    x: rightX + 0.2, y: boxY + 1.1, w: boxW - 0.4, h: 1.0,
    fontSize: 12, fontFace: "Calibri",
    color: "555555", align: "left", valign: "top", margin: 0, paraSpaceAfter: 4
  });

  // Arrow between
  slide.addText("→", {
    x: 4.55, y: boxY + 0.8, w: 0.5, h: 0.5,
    fontSize: 24, fontFace: "Arial", bold: true,
    color: theme.primary, align: "center", valign: "middle", margin: 0
  });

  // Impact callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.2, w: 9, h: 0.65,
    fill: { color: "FFFFFF" }, line: { color: theme.accent, width: 1 }
  });
  slide.addText([
    { text: "Impact: ", options: { bold: true, color: theme.accent } },
    { text: "Removing Length-Adaptive GAE drops AIME 2024 score from 60 to 45 (−15 points). This novel technique addresses the heterogeneous sequence length problem unique to long-CoT reasoning." }
  ], {
    x: 0.7, y: 4.2, w: 8.6, h: 0.65,
    fontSize: 12, fontFace: "Calibri",
    color: "444444", align: "left", valign: "middle", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("5", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e76f51", light: "f4a261", bg: "F5F0E8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

