const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 7, title: 'Training Efficiency' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("Training Efficiency: SOTA in 5K Steps with Zero Crashes", {
    x: 0.5, y: 0.25, w: 9, h: 0.55,
    fontSize: 22, fontFace: "Georgia", bold: true,
    color: theme.primary, align: "left", margin: 0, fit: "shrink"
  });

  // Left panel: training curve data (figure_2 reference)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.0, w: 4.5, h: 3.3,
    fill: { color: "FFFFFF" }, line: { color: "E0E0E0", width: 1 }
  });
  slide.addText("Training Curve — AIME 2024 Accuracy", {
    x: 0.7, y: 1.1, w: 4.1, h: 0.3,
    fontSize: 12, fontFace: "Calibri", bold: true,
    color: theme.primary, align: "left", margin: 0
  });
  slide.addText("(figure_2.jpg)", {
    x: 0.7, y: 1.4, w: 4.1, h: 0.25,
    fontSize: 10, fontFace: "Calibri", italic: true,
    color: "999999", align: "left", margin: 0
  });

  // Key data points from training curve
  const curveData = [
    { model: "VAPO", step: "~4,500", score: "60%", color: theme.accent },
    { model: "DAPO", step: "~5,500", score: "50%", color: theme.light },
    { model: "DeepSeek-R1-Zero", step: "~10,000", score: "47%", color: theme.secondary }
  ];

  curveData.forEach((d, i) => {
    const y = 1.85 + i * 0.65;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.9, y: y, w: 0.12, h: 0.4,
      fill: { color: d.color }
    });
    slide.addText([
      { text: d.model, options: { bold: true, fontSize: 12 } },
      { text: `  →  ${d.score} at step ${d.step}`, options: { fontSize: 11, color: "666666" } }
    ], {
      x: 1.15, y: y, w: 3.5, h: 0.4,
      fontFace: "Calibri", color: theme.primary,
      align: "left", valign: "middle", margin: 0
    });
  });

  slide.addText("VAPO consistently outperforms DAPO throughout the entire training run.", {
    x: 0.7, y: 3.75, w: 4.1, h: 0.3,
    fontSize: 10, fontFace: "Calibri", italic: true,
    color: "888888", align: "left", margin: 0
  });

  // Right panel: response length + stability
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.0, w: 4.4, h: 3.3,
    fill: { color: "FFFFFF" }, line: { color: "E0E0E0", width: 1 }
  });
  slide.addText("Response Length & Stability", {
    x: 5.5, y: 1.1, w: 4.0, h: 0.3,
    fontSize: 12, fontFace: "Calibri", bold: true,
    color: theme.primary, align: "left", margin: 0
  });
  slide.addText("(figure_3.jpg)", {
    x: 5.5, y: 1.4, w: 4.0, h: 0.25,
    fontSize: 10, fontFace: "Calibri", italic: true,
    color: "999999", align: "left", margin: 0
  });

  // Response length stats
  slide.addText("~6,000", {
    x: 5.5, y: 1.85, w: 2.0, h: 0.6,
    fontSize: 32, fontFace: "Georgia", bold: true,
    color: theme.accent, align: "left", margin: 0
  });
  slide.addText("tokens (VAPO)", {
    x: 7.5, y: 1.95, w: 2.0, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "666666", align: "left", valign: "middle", margin: 0
  });
  slide.addText("~4,500", {
    x: 5.5, y: 2.5, w: 2.0, h: 0.6,
    fontSize: 32, fontFace: "Georgia", bold: true,
    color: theme.secondary, align: "left", margin: 0
  });
  slide.addText("tokens (DAPO)", {
    x: 7.5, y: 2.6, w: 2.0, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "666666", align: "left", valign: "middle", margin: 0
  });

  slide.addShape(pres.shapes.LINE, {
    x: 5.5, y: 3.25, w: 3.8, h: 0,
    line: { color: "E0E0E0", width: 1 }
  });

  slide.addText([
    { text: "Zero training crashes ", options: { bold: true, color: theme.accent } },
    { text: "across multiple independent runs. VAPO learns more elaborate reasoning chains while maintaining complete training stability." }
  ], {
    x: 5.5, y: 3.4, w: 3.8, h: 0.8,
    fontSize: 11, fontFace: "Calibri",
    color: "555555", align: "left", valign: "top", margin: 0
  });

  // Page badge
