    color: theme.primary, align: "left", margin: 0, fit: "shrink"
  });

  // Waterfall-style horizontal bar chart showing score when each component is removed
  // Sorted by impact (most impactful removal first)
  const ablations = [
    { label: "VAPO (full)", value: 60, color: theme.accent, isFull: true },
    { label: "w/o Value-Pretraining", value: 11, color: "C0392B", drop: 49 },
    { label: "w/o Decoupled-GAE", value: 33, color: "E67E22", drop: 27 },
    { label: "w/o Length-Adaptive GAE", value: 45, color: theme.light, drop: 15 },
    { label: "w/o Clip-Higher", value: 46, color: "F5C451", drop: 14 },
    { label: "w/o Token-level Loss", value: 53, color: theme.secondary, drop: 7 },
    { label: "w/o Pos. Example LM Loss", value: 54, color: "76C7B7", drop: 6 },
    { label: "w/o Group-Sampling", value: 55, color: "A8D5C8", drop: 5 }
  ];

  // Table-style layout
  const tableX = 0.5;
  const tableW = 9;
  const rowH = 0.45;
  const startY = 1.05;
  const labelW = 3.2;
  const barAreaX = tableX + labelW;
  const barAreaW = tableW - labelW - 1.0;
  const scoreW = 1.0;

  // Header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: tableX, y: startY, w: tableW, h: rowH,
    fill: { color: theme.primary }
  });
  slide.addText("Configuration", {
    x: tableX + 0.1, y: startY, w: labelW - 0.1, h: rowH,
    fontSize: 11, fontFace: "Calibri", bold: true,
    color: "FFFFFF", align: "left", valign: "middle", margin: 0
  });
  slide.addText("AIME 2024 Score", {
    x: barAreaX, y: startY, w: barAreaW, h: rowH,
    fontSize: 11, fontFace: "Calibri", bold: true,
    color: "FFFFFF", align: "center", valign: "middle", margin: 0
  });
  slide.addText("Δ", {
    x: tableX + tableW - scoreW, y: startY, w: scoreW, h: rowH,
    fontSize: 11, fontFace: "Calibri", bold: true,
    color: "FFFFFF", align: "center", valign: "middle", margin: 0
  });

  ablations.forEach((a, i) => {
    const ry = startY + rowH + i * rowH;
    const bgColor = i % 2 === 0 ? "FFFFFF" : "F8F6F0";

    // Row bg
    slide.addShape(pres.shapes.RECTANGLE, {
      x: tableX, y: ry, w: tableW, h: rowH,
      fill: { color: bgColor }
    });

    // Label
    slide.addText(a.label, {
      x: tableX + 0.1, y: ry, w: labelW - 0.1, h: rowH,
      fontSize: 11, fontFace: "Calibri", bold: a.isFull ? true : false,
      color: a.isFull ? theme.accent : "444444",
      align: "left", valign: "middle", margin: 0
    });

    // Bar
    const maxVal = 60;
    const barW = (a.value / maxVal) * barAreaW;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: barAreaX, y: ry + 0.08, w: barW, h: rowH - 0.16,
      fill: { color: a.color }
    });

    // Score label
    slide.addText(String(a.value), {
      x: barAreaX + barW + 0.05, y: ry, w: 0.5, h: rowH,
      fontSize: 10, fontFace: "Calibri", bold: true,
      color: "444444", align: "left", valign: "middle", margin: 0
    });

    // Delta
    if (!a.isFull) {
      slide.addText(`−${a.drop}`, {
        x: tableX + tableW - scoreW, y: ry, w: scoreW, h: rowH,
        fontSize: 11, fontFace: "Calibri", bold: true,
        color: "C0392B", align: "center", valign: "middle", margin: 0
      });
    }
  });

  // Highlight callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.85, w: 9, h: 0.45,
    fill: { color: "FFF0EB" }, line: { color: theme.accent, width: 1 }
  });
  slide.addText([
    { text: "Critical: ", options: { bold: true, color: theme.accent } },
    { text: "Removing Value-Pretraining drops score from 60 → 11. Without it, value-model-based RL barely works. The top three components (Value-Pretraining, Decoupled-GAE, Length-Adaptive GAE) collectively contribute 91% of the gain." }
  ], {
    x: 0.7, y: 4.85, w: 8.6, h: 0.45,
    fontSize: 11, fontFace: "Calibri",
    color: "444444", align: "left", valign: "middle", margin: 0
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("8", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Calibri", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "264653", secondary: "2a9d8f", accent: "e76f51", light: "f4a261", bg: "F5F0E8" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

